package com.jarvis.ai;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.provider.Settings;import android.speech.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.core.app.ActivityCompat;import androidx.core.content.ContextCompat;import java.util.*;
public class MainActivity extends AppCompatActivity{
private static final int MIC=50,SPEECH=60;private TextView status,transcript,subtitle;private JarvisEngine engine;private JarvisTts tts;private JarvisActionExecutor executor;private final JarvisCommandRouter router=new JarvisCommandRouter();
@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);status=findViewById(R.id.status);transcript=findViewById(R.id.transcript);subtitle=findViewById(R.id.subtitle);engine=new JarvisEngine(this);tts=new JarvisTts(this);executor=new JarvisActionExecutor(this);findViewById(R.id.micButton).setOnClickListener(v->listen());findViewById(R.id.brain).setOnClickListener(v->toggleWake());findViewById(R.id.settings).setOnClickListener(v->settings());findViewById(R.id.history).setOnClickListener(v->showHistory());if(getIntent().getBooleanExtra("wake",false))new Handler().postDelayed(this::listen,350);}
private boolean mic(){return ContextCompat.checkSelfPermission(this,Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED;}
private void toggleWake(){if(!mic()){ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.RECORD_AUDIO},MIC);return;}status.setVisibility(TextView.VISIBLE);if(JarvisWakeService.isRunning()){stopService(new Intent(this,JarvisWakeService.class));status.setText("Wake listener stopped");subtitle.setText("Tap the microphone to speak");}else{ContextCompat.startForegroundService(this,new Intent(this,JarvisWakeService.class));status.setText("Wake listener active");subtitle.setText("Listening for “Hey Jarvis”");}}
private void listen(){if(!mic()){ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.RECORD_AUDIO},MIC);return;}Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,false);startActivityForResult(i,SPEECH);status.setVisibility(TextView.VISIBLE);status.setText("Listening…");subtitle.setText("I'm listening");}
@Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r!=SPEECH||d==null)return;ArrayList<String>a=d.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(a==null||a.isEmpty())return;String cmd=a.get(0);transcript.setText(cmd);transcript.setVisibility(TextView.VISIBLE);execute(cmd);}
private void execute(String cmd){JarvisAction a=router.route(cmd);if(a.confirmation)new AlertDialog.Builder(this).setTitle("JARVIS Confirmation").setMessage("এই কাজটি করতে অনুমতি দেবেন?\n"+cmd).setNegativeButton("Cancel",null).setPositiveButton("Confirm",(d,w)->run(a)).show();else run(a);}
private void run(JarvisAction a){if(a.type==JarvisAction.Type.ASK_AI){status.setVisibility(TextView.VISIBLE);status.setText("Thinking…");new Thread(()->{String answer=engine.ask(a.value);runOnUiThread(()->{status.setText("Ready");subtitle.setText(answer);tts.speak(answer);});}).start();return;}String result;if(a.type==JarvisAction.Type.HOME||a.type==JarvisAction.Type.BACK||a.type==JarvisAction.Type.RECENTS||a.type==JarvisAction.Type.NOTIFICATIONS||a.type==JarvisAction.Type.QUICK_SETTINGS||a.type==JarvisAction.Type.SCROLL_UP||a.type==JarvisAction.Type.SCROLL_DOWN||a.type==JarvisAction.Type.OPEN_APP)result=executor.execute(a);else if(a.type==JarvisAction.Type.CALL)result="Call confirmation accepted. Phone-number/contact resolution can be added next.";else if(a.type==JarvisAction.Type.SMS)result="SMS confirmation accepted. Message/contact composition can be added next.";else result="Done.";status.setVisibility(TextView.VISIBLE);status.setText(result);subtitle.setText(result);tts.speak(result);}
private void showHistory(){String last=transcript.getText().toString();new AlertDialog.Builder(this).setTitle("JARVIS History").setMessage(last==null||last.isEmpty()?"No recent command yet.":last).setPositiveButton("OK",null).show();}
private void settings(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(30,10,30,10);EditText gem=new EditText(this);gem.setHint("Gemini API key");gem.setInputType(129);EditText open=new EditText(this);open.setHint("OpenAI API key");open.setInputType(129);EditText groq=new EditText(this);groq.setHint("Groq API key");groq.setInputType(129);EditText custom=new EditText(this);custom.setHint("Custom API key");custom.setInputType(129);EditText endpoint=new EditText(this);endpoint.setHint("Custom OpenAI-compatible endpoint");Spinner primary=new Spinner(this);String[]ps={"Gemini","OpenAI-compatible","Groq","Custom"};primary.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,ps));Button phone=new Button(this);phone.setText("ENABLE PHONE CONTROL");Button clear=new Button(this);clear.setText("CLEAR LOCAL MEMORY");phone.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));clear.setOnClickListener(v->{engine.memory().clear();Toast.makeText(this,"Local memory cleared.",Toast.LENGTH_SHORT).show();});box.addView(primary);box.addView(gem);box.addView(open);box.addView(groq);box.addView(custom);box.addView(endpoint);box.addView(phone);box.addView(clear);new AlertDialog.Builder(this).setTitle("JARVIS Settings").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{if(gem.getText().length()>0)SecureStore.put(this,"gemini",gem.getText().toString());if(open.getText().length()>0)SecureStore.put(this,"openai",open.getText().toString());if(groq.getText().length()>0)SecureStore.put(this,"groq",groq.getText().toString());if(custom.getText().length()>0)SecureStore.put(this,"custom",custom.getText().toString());if(endpoint.getText().length()>0)SecureStore.put(this,"custom_endpoint",endpoint.getText().toString());SecureStore.put(this,"primary",primary.getSelectedItem().toString());status.setVisibility(TextView.VISIBLE);status.setText("AI settings saved securely.");}).show();}
@Override protected void onDestroy(){if(tts!=null)tts.shutdown();super.onDestroy();}}